#include <stdio.h>
#include <time.h>
int main(void) {
 time_t now = time(NULL);
 if (now == (time_t)-1) return 1;
 struct tm *parts = localtime(&now);
 if (parts == NULL) return 1;
 char text[64];
 if (strftime(text, sizeof text, "%Y-%m-%d %H:%M:%S", parts) == 0) return 1;
 puts(text);
 return 0;
}
